const express = require("express");
const db = require("../db");

const router = express.Router();

router.post("/", async (req, res) => {
  const idempotencyKey = req.get("Idempotency-Key");

  if (idempotencyKey) {
    const cached = await db.query(
      "SELECT response FROM idempotency_keys WHERE key = $1 AND account_id = $2",
      [idempotencyKey, req.user.accountId]
    );
    if (cached.length) {
      return res.status(201).json(cached[0].response);
    }
  }

  const row = await db.write(
    "INSERT INTO orders (account_id, sku, quantity) VALUES ($1, $2, $3) RETURNING *",
    [req.user.accountId, req.body.sku, req.body.quantity]
  );

  if (idempotencyKey) {
    await db.write(
      "INSERT INTO idempotency_keys (key, account_id, response) VALUES ($1, $2, $3)",
      [idempotencyKey, req.user.accountId, JSON.stringify(row)]
    );
  }

  res.status(201).json(row);
});

router.patch("/:id/cancel", async (req, res) => {
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 RETURNING *",
    [req.params.id, req.user.accountId]
  );
  if (!row) return res.status(403).end();
  res.json(row);
});

module.exports = router;

