async function sessionUser(req, res, next) {
  const rows = await db.query(
    "SELECT u.id, u.email, u.account_id FROM sessions s JOIN users u ON u.id = s.user_id JOIN accounts a ON u.account_id = a.id WHERE s.token = $1 AND s.expires_at > now() AND a.deleted_at IS NULL",
