const { Pool } = require("pg");

const pool = new Pool();

// Every read in the service goes through query(). Every write goes through
// write() — it exists so callers get the RETURNING row back in one shape and
// so there is exactly one place a transaction begins.
async function query(text, params) {
  const res = await pool.query(text, params);
  return res.rows;
}

async function write(text, params) {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const res = await client.query(text, params);
    await client.query("COMMIT");
    return res.rows[0];
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  } finally {
    client.release();
  }
}

async function idempotentWrite(idempotencyKey, userId, writeFunc) {
  const existing = await query(
    "SELECT result FROM idempotency_keys WHERE key = $1 AND user_id = $2",
    [idempotencyKey, userId]
  );
  if (existing.length) {
    return JSON.parse(existing[0].result);
  }
  const result = await writeFunc();
  await write(
    "INSERT INTO idempotency_keys (key, user_id, result) VALUES ($1, $2, $3)",
    [idempotencyKey, userId, JSON.stringify(result)]
  );
  return result;
}

module.exports = { query, write, idempotentWrite };

