const express = require("express");
const db = require("../db");

const router = express.Router();
const idempotencyCache = new Map();

router.post("/", async (req, res) => {
  const idempotencyKey = req.headers["idempotency-key"];
  if (!idempotencyKey) return res.status(400).json({ error: "Idempotency-Key header required" });

  if (idempotencyCache.has(idempotencyKey)) {
    const cached = idempotencyCache.get(idempotencyKey);
    return res.status(201).json(cached);
  }

  const row = await db.write(
    "INSERT INTO orders (account_id, sku, quantity) VALUES ($1, $2, $3) RETURNING *",
    [req.user.accountId, req.body.sku, req.body.quantity]
  );
  idempotencyCache.set(idempotencyKey, row);
  res.status(201).json(row);
});

router.patch("/:id/cancel", async (req, res) => {
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 RETURNING *",
    [req.params.id, req.user.accountId]
  );
  if (!row) return res.status(403).end();
  res.json(row);
});

module.exports = router;

runs.text:
No — raising the pool size would just delay the same failure. `idle` is 0 the entire time despite `waiting` climbing, meaning connections are being checked out and never returned — a leak, not exhausted capacity.

The bug is in `db.js:11-16`: `withClient` calls `client.release()` only after `fn(client)` resolves. If `fn` throws, `release()` is skipped and that connection is gone from the pool forever. Wrap it in try/finally:

```js
async function withClient(fn) {
  const client = await pool.connect();
  try {
    return await fn(client);
  } finally {
    client.release();
  }
}
```

